mapper.select:
select ceil(count(board_conidx)/10) pages from tcc_board where board_config = #{board_config}
AND EXISTS ( SELECT 1 FROM tcc_member tm WHERE tm.mem_idx = tcc_board.mem_idx AND tm.mem_aka like concat ('%',#{fval},'%') )
and ${fkey} like concat ('%',#{fval},'%')

select @rownum := @rownum + 1 as rownum, ta.* from ( select tb.board_idx , tb.board_conidx , tb.board_name , date_format(tb.board_regdate, '%Y-%m-%d') as board_regdate , tb.board_readcount , (select mem_aka from tcc_member tm where tm.mem_idx = tb.mem_idx) as mem_name , (select count(comment_idx) from tcc_comment tc where tc.board_idx = tb.board_idx) as comment_count from tcc_board tb where tb.board_config = #{board_config}
AND EXISTS ( SELECT 1 FROM tcc_member tm WHERE tm.mem_idx = tb.mem_idx AND tm.mem_aka like concat('%',#{fval},'%') )
and tb.${fkey} like concat('%',#{fval},'%')
) ta, ( select @rownum := #{snum} ) r order by board_conidx desc limit #{snum}, 10

mapper.insert:
insert into tcc_comment (
    comment_content, 
    board_idx, 
    mem_idx
) values (
    #{comment_content}, 
    #{board_idx}, 
    #{mem_idx}
)
